 "content": "def transform(grid):
    """Recolor every 4-connected group of at least two zero cells to 8."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            queue = [(r, c)]
            seen.add((r, c))
            component = []
            for y, x in queue:
                component.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        queue.append((ny, nx))
            if len(component) > 1:
                for y, x in component:
                    out[y][x] = 8
    return out
